+// Sales from the till. Each dish sold uses one portion of its recipe per unit
+// of `qty`; the ingredients are consumed with ref `sale:<ticket>`. A ticket is
+// imported once. Recording a set of sales is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines [{ row, ticket, soldAt, dishId, qty }] and consumes their
+ * ingredients. Lines of tickets already imported are skipped. Checks every
+ * line first; throws (changing nothing) naming the first row that fails.
+ * Returns { tickets, dishes } for what was imported.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !ticketImported(store, l.ticket));
+  const planned = [];
+  const need = new Map();
+  for (const l of fresh) {
+    let dish;
+    try {
+      dish = getDish(store, l.dishId);
+    } catch {
+      throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    }
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    for (const u of uses) {
+      const item = getItem(store, u.itemId);
+      const total = round3((need.get(u.itemId) ?? 0) + u.qty);
+      const available = round3(onHand(store, u.itemId));
+      if (total > available)
+        throw new AppError("import_not_enough_stock", { row: l.row, item: item.name, available, unit: item.unit });
+      need.set(u.itemId, total);
+    }
+    planned.push({ line: l, uses });
+  }
+  store.data.sales ??= [];
+  for (const { line, uses } of planned) {
+    const ref = `sale:${line.ticket}`;
+    for (const u of uses) consume(store, u.itemId, u.qty, { at: line.soldAt, ref });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty, uses });
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
